//! refine_matte: classical (NON-ML) trimap alpha matting for hair/blur/glass edges. See src/matting.rs.
use super::kit::*;
use crate::matte::{self, Store};
use crate::matting;

fn pts(v: &Value, w: f64, h: f64) -> Result<Vec<[f64; 2]>, String> { let a = v.as_array().ok_or("points must be an array")?; let mut o: Vec<[f64; 2]> = vec![];
    for p in a { let q = p.as_array().ok_or("each point is [x,y]")?; o.push([q.first().and_then(|v| v.as_f64()).ok_or("bad point")?, q.get(1).and_then(|v| v.as_f64()).ok_or("bad point")?]); }
    if o.iter().all(|p| p[0].abs() <= 1.5 && p[1].abs() <= 1.5) { for p in o.iter_mut() { p[0] *= w; p[1] *= h; } } Ok(o) }
fn write_gray_png(path: &str, d: &[f32], w: usize, h: usize, rgb: bool) -> Result<(), String> {
    use std::io::Write; let (fmt, ch) = if rgb { ("rgb24", 3) } else { ("gray", 1) }; let mut c = std::process::Command::new("ffmpeg").args(["-y", "-loglevel", "error", "-f", "rawvideo", "-pix_fmt", fmt, "-s", &format!("{w}x{h}"), "-i", "-", "-frames:v", "1", path]).stdin(std::process::Stdio::piped()).spawn().map_err(|e| format!("ffmpeg: {e}"))?;
    let bytes: Vec<u8> = d.iter().take(w * h * ch).map(|v| (v.clamp(0.0, 1.0) * 255.0 + 0.5) as u8).collect(); c.stdin.take().unwrap().write_all(&bytes).map_err(|e| e.to_string())?; let st = c.wait().map_err(|e| e.to_string())?; if st.success() { Ok(()) } else { Err("ffmpeg png write failed".into()) } }

pub fn commands() -> Vec<Command> { vec![
    Command { name: "refine_matte", description: "Turn a rough subject outline into a true soft alpha matte for hair and edges (classical, no machine learning). Hair/edge-quality alpha matting (CLASSICAL, NOT machine learning; no neural network or learned prior is used): turns a rough subject outline into a true soft alpha. Builds a trimap (sure-fg / unknown band / sure-bg) around the rough edge, estimates alpha for every unknown pixel from the best foreground/background colour pair sampled nearby, smooths it with an edge-aware colour guided filter, and estimates the foreground colour. Keeps partial alpha on hair strands, motion blur and glass. Seed from either `points` (a polygon at clip-local `time`) or `matte_dir` (the dir returned by track_matte; refines every frame in start..end, up to 240). Quality depends on the outline: auto_bg removes background-coloured regions that connect to the outside, and exclude/include polygons correct the rest, but a backdrop close in colour to the subject (pink wall, pink jacket) can still leak or eat into the subject, so inspect the result. Limits: it needs foreground and background colours to differ locally; when they match (grey hair on grey wall) alpha stays at the seed's value, and frames whose confidence is low are listed. Result: a new `matte` mask layer (mask_id) on the clip and per-frame stats; out_png writes the alpha (and fg_png the decontaminated foreground) for the first frame.", mutates: true,
        schema: obj(vec![("clip_id", s("media clip")), ("time", n("clip-local seconds of the seed outline (points mode)")), ("points", json!({"type":"array","description":"rough outline [[x,y],..] canvas px or 0..1 normalised"})), ("matte_dir", s("dir from track_matte to refine frame by frame")), ("start", n("clip-local s, default 0 (matte_dir mode)")), ("end", n("clip-local s, default clip end")), ("band", n("half-width px of the unknown band around the seed edge, default 8; widen for sloppy seeds or long hair")), ("samples", n("foreground/background colour samples per pixel, 3..24, default 10")), ("guide_radius", n("guided filter radius px, default 4")), ("auto_bg", json!({"type":"boolean","description":"default true: reclaim background-coloured pixels inside the outline that connect to the outside background, so a loose outline does not leave wall in the matte"})), ("bg_bounds", json!({"type":"boolean","description":"default true: clamp unknown-band alpha by colour distance to the local background model (kills wall residue; applies only when the sure-background pixels are near-uniform, i.e. their RMS colour deviation from the local model is below 0.10; reported per frame as bg_rms/bounds_used). Set false for busy or similar-coloured backgrounds. The synthetic hair test is run with this off."})), ("bg_threshold", n("auto_bg colour distance 0.01..0.4 (0..1 RGB), default 0.07; lower = more conservative")), ("exclude", json!({"type":"array","description":"extra polygons [[[x,y],..],..] forced to background (stroke-like corrections)"})), ("include", json!({"type":"array","description":"extra polygons forced to foreground"})), ("dir", s("output folder, default /tmp/kimo_refine_<clip>")), ("out_png", s("write refined alpha PNG of the first frame here")), ("fg_png", s("write estimated foreground colour PNG of the first frame here")), ("add_mask", json!({"type":"boolean","description":"attach as a matte mask layer (default true)"})), ("mode", s("mask combine mode, default add"))], &["clip_id"]),
        run: |ss, a| {
            let t0 = std::time::Instant::now(); let cid = str_arg(a, "clip_id")?.to_string(); let fps = ss.project.fps; let (w, h) = (ss.project.width as usize, ss.project.height as usize);
            let (cstart, cdur) = { let c = ss.project.find_clip(&cid).ok_or("no such clip")?; (c.start, c.duration) }; let nclip = ((cdur * fps).round() as usize).max(1);
            let band = opt_num(a, "band", 8.0).clamp(2.0, 60.0) as usize; let o = matting::Opts { band, samples: opt_num(a, "samples", 10.0).clamp(3.0, 24.0) as usize, guide_radius: opt_num(a, "guide_radius", 4.0).clamp(1.0, 24.0) as usize, bg_bounds: a.get("bg_bounds").and_then(|v| v.as_bool()).unwrap_or(true), ..Default::default() };
            let auto_bg = a.get("auto_bg").and_then(|v| v.as_bool()).unwrap_or(true); let bg_thr = opt_num(a, "bg_threshold", 0.07).clamp(0.01, 0.4) as f32;
            let polys = |key: &str| -> Result<Vec<Vec<[f64; 2]>>, String> { match a.get(key).and_then(|v| v.as_array()) { Some(l) => l.iter().map(|p| pts(p, w as f64, h as f64)).collect(), None => Ok(vec![]) } }; let (excl, incl) = (polys("exclude")?, polys("include")?);
            let (f0, f1, seeds): (usize, usize, Vec<Vec<f32>>) = if let Some(dir) = a.get("matte_dir").and_then(|v| v.as_str()) {
                let st = matte::load(dir).ok_or("matte_dir not found or invalid; use the dir returned by track_matte")?; let first = opt_num(a, "start", 0.0); let f0 = (first * fps).round().max(0.0) as usize; let f1 = ((opt_num(a, "end", cdur) * fps).round() as usize).min(nclip - 1).max(f0);
                if f1 + 1 - f0 > 240 { return Err("range too long (max 240 frames per call)".into()); }
                // store frame index 0 corresponds to the matte's own first frame; the track_matte mask layer's `start` prop maps it, here we take matte frame k for clip frame f0+k
                (f0, f1, (0..(f1 + 1 - f0).min(st.n)).map(|k| matte::frame_alpha(&st, k as f64, w, h)).collect())
            } else { let t = num_arg(a, "time")?; let f = (t * fps).round().max(0.0) as usize; if f >= nclip { return Err("time outside clip".into()); } let p = pts(a.get("points").ok_or("give points or matte_dir")?, w as f64, h as f64)?; if p.len() < 3 { return Err("outline needs at least 3 points".into()); } (f, f, vec![matte::raster_poly(&p, w, h)]) };
            let mut out = vec![0u8; seeds.len() * w * h]; let mut stats = vec![]; let mut first_alpha: Option<(Vec<f32>, Vec<f32>)> = None;
            for (k, seed) in seeds.iter().enumerate() { let f = f0 + k; let t = cstart + f as f64 / fps; crate::render::prepare_at(&ss.project, &mut ss.cache, Some(t))?; let fr = crate::render::render_clip_alone(&ss.project, &cid, t, &ss.cache).ok_or("could not render the clip")?;
                let mut img = vec![0f32; w * h * 3]; for i in 0..w * h { for c in 0..3 { img[i * 3 + c] = fr.d[i * 4 + c].clamp(0.0, 1.0); } }
                let mut seed = seed.clone(); for pg in &excl { let r = matte::raster_poly(pg, w, h); for i in 0..w * h { if r[i] > 0.5 { seed[i] = 0.0; } } } for pg in &incl { let r = matte::raster_poly(pg, w, h); for i in 0..w * h { if r[i] > 0.5 { seed[i] = 1.0; } } }
                let mut reclaimed = 0usize; if auto_bg { let (s2, c) = matting::auto_background(&img, &seed, w, h, band, bg_thr); seed = s2; reclaimed = c; }
                let seed = &seed; let tri = matting::trimap_from_alpha(seed, w, h, band); let m = matting::matte(&img, &tri, w, h, &o);
                for i in 0..w * h { out[k * w * h + i] = (m.alpha[i] * 255.0 + 0.5) as u8; }
                let partial = m.alpha.iter().filter(|&&v| v > 0.02 && v < 0.98).count(); let changed: f64 = (0..w * h).filter(|&i| m.trimap[i] == 128).map(|i| (m.alpha[i] - seed[i]).abs() as f64).sum::<f64>() / m.unknown.max(1) as f64;
                stats.push(json!({"frame": f, "auto_bg_reclaimed_px": reclaimed, "bg_rms": (m.bg_rms * 10000.0).round() / 10000.0, "bounds_used": m.bounds_used, "unknown_px": m.unknown, "partial_alpha_px": partial, "mean_change_vs_seed": (changed * 1000.0).round() / 1000.0}));
                if k == 0 { first_alpha = Some((m.alpha, m.fg)); } }
            let dir = a.get("dir").and_then(|v| v.as_str()).map(|x| x.to_string()).unwrap_or_else(|| format!("/tmp/kimo_refine_{cid}")); matte::save(&dir, &Store { w, h, n: seeds.len(), d: out })?;
            if let Some((al, fg)) = &first_alpha { if let Some(p) = a.get("out_png").and_then(|v| v.as_str()) { write_gray_png(p, al, w, h, false)?; } if let Some(p) = a.get("fg_png").and_then(|v| v.as_str()) { write_gray_png(p, fg, w, h, true)?; } }
            let mut res = json!({"method": "classical trimap matting (not ML)", "dir": dir, "frames": seeds.len(), "first_frame_s": f0 as f64 / fps, "seconds": t0.elapsed().as_secs_f64(), "per_frame": if stats.len() > 12 { json!(stats.iter().step_by(stats.len() / 12 + 1).cloned().collect::<Vec<_>>()) } else { json!(stats) }});
            if a.get("add_mask").and_then(|v| v.as_bool()).unwrap_or(true) { let id = ss.project.gen_id("mask"); let mut l = crate::masks::new_layer(id.clone(), "matte"); l.strings.insert("dir".into(), dir.clone()); l.props.insert("start".into(), crate::keyframe::Prop::new(f0 as f64 / fps)); if let Some(m) = a.get("mode").and_then(|v| v.as_str()) { l.mode = m.into(); }
                let c = ss.project.find_clip_mut(&cid).ok_or("no such clip")?; let m = c.mask.get_or_insert_with(|| crate::model::Mask { shape: "stack".into(), props: Default::default(), invert: false, layers: vec![], matte: None }); m.layers.push(l); res["mask_id"] = json!(id); }
            Ok(res) } },
] }
